import type { EngineInterface, Register, Timer } from 'claude-code'

import { COLOR, ICON, cleanLines, elapsed, parseNotifications, parseStart, timelineSvg } from './lib'
import type { Task } from './lib'

const PANE = 'bg-watch'
// `/bg` is the built-in /background's alias.
const COMMAND = 'bg-watch'
const TAIL_LINES = 300
const LIST_ROWS = 5

// Module state: what the hooks record, the pane draws. A reload starts it over.
const tasks = new Map<string, Task>()
const tails = new Map<string, string[]>()
const sizes = new Map<string, number>()
let selected: string | null = null
let isOpen = false
let isClosedByPerson = false
let ticker: Timer | null = null

function current(): Task | undefined {
  if (selected && tasks.has(selected)) return tasks.get(selected)
  const all = [...tasks.values()]
  return all.reverse().find(t => t.status === 'running') ?? all[0]
}

function labelOf(t: Task, now: number): string {
  const took = elapsed((t.endedAt ?? now) - t.startedAt)
  const exit = t.exitCode !== undefined && t.exitCode !== 0 ? ` · exit ${t.exitCode}` : ''
  return `${ICON[t.status]} ${t.label} · ${took}${exit}`
}

function statusLine(): string | undefined {
  if (tasks.size === 0) return undefined
  const count = (s: Task['status']) => [...tasks.values()].filter(t => t.status === s).length
  const parts = [
    count('running') ? `${ICON.running}${count('running')}` : '',
    count('completed') ? `${ICON.completed}${count('completed')}` : '',
    count('failed') ? `${ICON.failed}${count('failed')}` : '',
  ].filter(Boolean)
  return `bg ${parts.join(' ')}`
}

async function readTail($: EngineInterface, t: Task): Promise<void> {
  if (!t.outputFile) return
  try {
    const { size } = await $.fs.stat(t.outputFile)
    if (sizes.get(t.id) === size && tails.has(t.id)) return
    sizes.set(t.id, size)
    const r = await $.process.run(['tail', '-n', String(TAIL_LINES), t.outputFile], { timeoutMs: 5_000 })
    tails.set(t.id, cleanLines(r.stdout))
  } catch {
    // The file can vanish once the session cleans up its tasks folder.
  }
}

async function tick($: EngineInterface): Promise<void> {
  const t = current()
  if (t && isOpen) await readTail($, t)
  // The pane already shows all of this; the status line is for when it's closed.
  $.ui.status(isOpen ? undefined : statusLine())
  $.ui.invalidate('ui.render')
  const isIdle = ![...tasks.values()].some(x => x.status === 'running')
  if (isIdle && !isOpen && ticker) {
    ticker.cancel()
    ticker = null
  }
}

function startTicker($: EngineInterface): void {
  ticker ??= $.clock.every(1_000, () => void tick($))
}

async function textSummary($: EngineInterface): Promise<string> {
  if (tasks.size === 0) return 'No background commands in this session yet.'
  const now = await $.clock.now()
  const rows = [...tasks.values()].reverse().map(t => labelOf(t, now))
  const t = current()
  if (!t) return rows.join('\n')
  await readTail($, t)
  const tail = (tails.get(t.id) ?? []).slice(-15)
  const where = t.outputFile ? `\n(full output: ${t.outputFile})` : ''
  return [...rows, '', `── ${t.label} ──`, ...tail].join('\n') + where
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    try {
      await $.command.register({
        name: COMMAND,
        description: "Show Claude's background commands and their live output",
        argumentHint: '[text]',
        // Background commands matter most while Claude is mid-turn.
        immediate: true,
      })
    } catch (error) {
      // The pane and toasts still work without the command.
      $.ui.toast(`bg-watch: /${COMMAND} unavailable (${String(error).slice(0, 80)})`)
    }
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    if (e.args.trim() === 'text') return { text: await textSummary($) }
    isClosedByPerson = false
    const opened = await $.ui.open({ id: PANE, title: 'Background', rows: 16 })
    if (!opened.isPlaced) return { text: await textSummary($) }
    isOpen = true
    startTicker($)
    void tick($)
    return { text: 'Background pane opened.' }
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    const result = ran.result as { backgroundTaskId?: string } | undefined
    const id = result?.backgroundTaskId
    if (!id || tasks.has(id)) return ran

    const start = parseStart(ran.text)
    tasks.set(id, {
      id,
      label: e.description?.trim() || (e.command.split('\n')[0] ?? '').slice(0, 60),
      command: e.command,
      outputFile: start?.outputFile,
      startedAt: await $.clock.now(),
      status: 'running',
    })
    selected = null
    startTicker($)
    if (!isClosedByPerson && !isOpen) {
      // Nothing draws under `claude -p` or the VS Code panel; tracking goes on.
      isOpen = await $.ui.open({ id: PANE, title: 'Background', rows: 16 }).then(
        opened => opened.isPlaced,
        () => false,
      )
    }
    void tick($)
    return ran
  })

  on('session.append', async ($, e, next) => {
    const text = JSON.stringify(e.message.content)
    if (!text.includes('task-notification')) return next(e)

    const now = await $.clock.now()
    for (const n of parseNotifications(text.replace(/\\n/g, '\n'))) {
      const t = tasks.get(n.id)
      if (!t || t.status !== 'running') continue
      t.status = n.status
      t.exitCode = n.exitCode
      t.endedAt = now
      t.outputFile ??= n.outputFile
      sizes.delete(t.id)
      await readTail($, t)
      if (n.status === 'failed') {
        $.ui.toast(`✗ ${t.label} failed${n.exitCode !== undefined ? ` (exit ${n.exitCode})` : ''}  ·  /${COMMAND}`)
      }
    }
    void tick($)
    return next(e)
  })

  on('ui.close', { id: PANE }, async ($, e, next) => {
    isOpen = false
    if (e.origin.kind === 'person') isClosedByPerson = true
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    isOpen = true
    const t = current()
    const now = await $.clock.now()

    // Desktop draws native controls and SVG; give it a layout of its own.
    if (e.surface === 'desktop') {
      const { Box, Text, Button, Select, Svg, Code } = $.ui.resolve(e)
      if (!t) {
        return (
          <Box flexDirection="column" padding={1} gap={1}>
            <Text bold>No background commands yet</Text>
            <Text dimColor>When Claude starts a long-running command, its output streams here.</Text>
          </Box>
        )
      }
      const recent = [...tasks.values()].reverse().slice(0, 8)
      const tail = (tails.get(t.id) ?? []).slice(-60).join('\n')
      return (
        <Box flexDirection="column" padding={1} gap={1}>
          <Box flexDirection="row" justifyContent="space-between" alignItems="center" gap={2}>
            <Select
              key="task"
              options={recent.map(x => ({ key: x.id, value: x.id, label: `${ICON[x.status]} ${x.label}` }))}
              value={t.id}
              onSelect={value => {
                selected = value
                sizes.delete(value)
                void tick($)
              }}
            />
            <Text color={COLOR[t.status]} bold>
              {t.status} · {elapsed((t.endedAt ?? now) - t.startedAt)}
              {t.exitCode ? ` · exit ${t.exitCode}` : ''}
            </Text>
          </Box>
          <Svg source={timelineSvg(recent, now)} alt="Timeline of background commands by status" />
          <Code source={`$ ${t.command}`} language="bash" wrap="wrap" />
          {tail ? (
            <Code source={tail} wrap="truncate-end" />
          ) : (
            <Text dimColor>{t.outputFile ? 'No output yet.' : 'Output file unknown until the command finishes.'}</Text>
          )}
          {selected ? (
            <Button
              key="follow"
              label="Follow latest"
              variant="secondary"
              onPress={() => {
                selected = null
                void tick($)
              }}
            />
          ) : null}
        </Box>
      )
    }

    const { Box, Text, Button } = $.ui.resolve(e)
    if (!t) {
      return (
        <Box flexDirection="column">
          <Text dimColor>No background commands yet.</Text>
          <Text dimColor>When Claude runs one, its output streams here.</Text>
        </Box>
      )
    }

    const recent = [...tasks.values()].reverse().slice(0, LIST_ROWS)
    const rows = Math.max(3, e.props.scroll.bodyRows - recent.length - 1)
    const lines = (tails.get(t.id) ?? []).slice(-rows)

    return (
      <Box flexDirection="column">
        {recent.map((x, i) => (
          <Box key={x.id} flexDirection="row">
            <Button
              key={`pick-${x.id}`}
              label={x.label}
              hotkey={String(i + 1)}
              plain
              dimColor={x.id !== t.id}
              onPress={() => {
                selected = x.id
                sizes.delete(x.id)
                void tick($)
              }}
            />
            <Text color={COLOR[x.status]} wrap="truncate-end">
              {'  '}
              {ICON[x.status]} {elapsed((x.endedAt ?? now) - x.startedAt)}
              {x.exitCode ? ` · exit ${x.exitCode}` : ''}
            </Text>
          </Box>
        ))}
        <Text color={COLOR[t.status]} wrap="truncate-end">
          {ICON[t.status]} {t.status} · $ {t.command.split('\n')[0] ?? ''}
        </Text>
        {lines.length === 0 ? (
          <Text dimColor>{t.outputFile ? 'No output yet.' : 'Output file unknown until the command finishes.'}</Text>
        ) : (
          lines.map((line, i) => (
            <Text key={`l${i}`} wrap="truncate-end">
              {line || ' '}
            </Text>
          ))
        )}
      </Box>
    )
  })
}

