export type TaskStatus = 'running' | 'completed' | 'failed' | 'killed'

export type Task = {
  id: string
  label: string
  command: string
  outputFile?: string
  startedAt: number
  endedAt?: number
  status: TaskStatus
  exitCode?: number
}

export type Notification = {
  id: string
  status: TaskStatus
  outputFile?: string
  exitCode?: number
}

// Bash answers a backgrounded command with this sentence; the path is where
// its output streams.
export function parseStart(text: string | undefined): { id: string; outputFile?: string } | null {
  if (!text) return null
  const id = /running in background with ID: (\w+)/.exec(text)?.[1]
  if (!id) return null
  const outputFile = /Output is being written to: (\S+?\.output)\b/.exec(text)?.[1]
  return { id, outputFile }
}

// A finished background command reaches the conversation as a
// <task-notification> block. The text may be JSON-escaped, so match tags only.
export function parseNotifications(text: string): Notification[] {
  const found: Notification[] = []
  for (const m of text.matchAll(/<task-notification>([\s\S]*?)<\/task-notification>/g)) {
    const body = m[1] ?? ''
    const id = /<task-id>(\w+)<\/task-id>/.exec(body)?.[1]
    const raw = /<status>(\w+)<\/status>/.exec(body)?.[1]
    if (!id || !raw) continue
    const exit = /exit code (\d+)/.exec(body)?.[1]
    found.push({
      id,
      status: raw === 'completed' ? 'completed' : raw === 'failed' ? 'failed' : 'killed',
      outputFile: /<output-file>([^<]+)<\/output-file>/.exec(body)?.[1],
      exitCode: exit === undefined ? undefined : Number(exit),
    })
  }
  return found
}

const ANSI = /\x1b\[[0-9;?]*[A-Za-z]|\x1b\][^\x07]*\x07/g

export function cleanLines(text: string): string[] {
  const lines = text
    .replace(ANSI, '')
    .replace(/\r(?!\n)/g, '\n')
    .split('\n')
    // Claude Code appends its own exit line; the pane shows the exit code already.
    .filter(line => !/^\[exited with code \d+\]$/.test(line.trim()))
  while (lines.length && (lines[lines.length - 1] ?? '').trim() === '') lines.pop()
  return lines
}

export function elapsed(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  if (m < 60) return `${m}m${String(s % 60).padStart(2, '0')}s`
  return `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}m`
}

export const ICON: Record<TaskStatus, string> = {
  running: '◐',
  completed: '✓',
  failed: '✗',
  killed: '■',
}

export const COLOR: Record<TaskStatus, string> = {
  running: 'yellow',
  completed: 'green',
  failed: 'red',
  killed: 'gray',
}

// Mid-tone fills that read on both light and dark themes.
const FILL: Record<TaskStatus, string> = {
  running: '#d4a72c',
  completed: '#2da44e',
  failed: '#cf222e',
  killed: '#8c959f',
}

function escapeXml(s: string): string {
  return s.replace(/[<>&"']/g, c => `&#${c.charCodeAt(0)};`)
}

// One bar per command on a shared time axis, newest at the top: where each
// started, how long it ran, and how it ended.
export function timelineSvg(list: readonly Task[], now: number, width = 640): string {
  const row = 22
  const labelW = Math.round(width * 0.38)
  const barW = width - labelW - 8
  const from = Math.min(...list.map(t => t.startedAt))
  const span = Math.max(1, now - from)
  const bars = list.map((t, i) => {
    const y = i * row
    const x = labelW + ((t.startedAt - from) / span) * barW
    const w = Math.max(3, (((t.endedAt ?? now) - t.startedAt) / span) * barW)
    const label = t.label.length > 34 ? `${t.label.slice(0, 33)}…` : t.label
    return (
      `<text x="0" y="${y + 15}" font-size="12" font-family="system-ui,sans-serif" fill="#8c959f">${escapeXml(label)}</text>` +
      `<rect x="${x.toFixed(1)}" y="${y + 5}" width="${w.toFixed(1)}" height="12" rx="3" fill="${FILL[t.status]}"/>`
    )
  })
  const height = list.length * row
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}">${bars.join('')}</svg>`
}
